        .layout_version
        .store(MPSC_LAYOUT_VERSION, Ordering::Relaxed);
    header.slot_size.store(slot_size, Ordering::Relaxed);
    header.capacity.store(capacity, Ordering::Relaxed);
    header
        .cache_line_size
        .store(CACHE_LINE_SIZE as u32, Ordering::Relaxed);
