    }

    /// The smallest depth the flavor's protocol runs at. The
    /// MPSC v0 ring's committed and released seq values coincide
    /// at capacity 1 and its `init` rejects it, so its cells
    /// start at 2.
    pub fn min_depth(self) -> u32 {
        match self {
            Flavor::Mpsc => 2,
            _ => 1,
