/// The tp-cell CLI.
#[derive(Parser, Debug)]
#[command(name = "tp-cell", version, about = TOP_ABOUT, max_term_width = 80)]
struct Cli {
    /// Ring flavor(s) to run
    ///
    /// One cell is a main -> worker -> main round trip over two
